# Candidate repair (B4) for TASK-BANK-014
def build_request(data):
    return {'path': '/transfers', 'body': {'source': data['source'], 'destination': data['destination'], 'amount': {'value': int(data['amount_cents']), 'currency': data['currency']}}, 'headers': {'Idempotency-Key': data['idempotency_key']}}
